// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.ui.screensimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.layout.*import androidx.compose.foundation.lazy.LazyColumnimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.automirrored.filled.ArrowBackimport androidx.compose.material3.*import androidx.compose.runtime.*import androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.unit.dpimport com.roshan.persona.ui.components.GlassPanelimport com.roshan.persona.ui.state.NousViewModelimport com.roshan.persona.ui.state.UiStateProvider@Composablefun LlmConfigScreen(stateProvider: UiStateProvider, onBack: () -> Unit, modifier: Modifier = Modifier) {    val localLlmLoaded by stateProvider.localLlmLoaded.collectAsState()    val localLlmName by stateProvider.localLlmModelName.collectAsState()    val cloudProvider by stateProvider.cloudProviderName.collectAsState()    val monthlyCost by stateProvider.monthlyCostUsd.collectAsState()    val monthlyBudget by stateProvider.monthlyBudgetUsd.collectAsState()    SettingScaffold("LLM Configuration", onBack, modifier) {        GlassPanel(title = "Monthly Budget") {            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {                Text("$%.2f / $%.2f".format(monthlyCost, monthlyBudget), style = MaterialTheme.typography.headlineLarge, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurface)                val pct = if (monthlyBudget > 0) (monthlyCost / monthlyBudget * 100).coerceIn(0f, 100f) else 0f                Text("%.1f%% used".format(pct), style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.onSurfaceVariant)            }        }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "Local Model") {            Row(verticalAlignment = Alignment.CenterVertically) {                Column(Modifier.weight(1f)) {                    Text(if (localLlmLoaded) "Loaded" else "Not loaded", style = MaterialTheme.typography.bodyLarge, color = MaterialTheme.colorScheme.onSurface)                    Text(localLlmName ?: "No model selected", style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.onSurfaceVariant)                }            }        }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "Cloud Providers") {            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {                Text("Active: ${cloudProvider ?: "None configured"}", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface)                Text("Supported: OpenAI, Anthropic, Google Gemini, Mistral, Groq", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant)            }        }    }}@Composablefun VoiceConfigScreen(stateProvider: UiStateProvider, onBack: () -> Unit, modifier: Modifier = Modifier) {    val sttEngine by stateProvider.sttEngineName.collectAsState()    val ttsEngine by stateProvider.ttsEngineName.collectAsState()    val wakeWordActive by stateProvider.wakeWordActive.collectAsState()    val speakerCount by stateProvider.speakerCount.collectAsState()    SettingScaffold("Voice Configuration", onBack, modifier) {        GlassPanel(title = "Speech-to-Text (STT)") { Text("Engine: $sttEngine", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "Text-to-Speech (TTS)") { Text("Engine: $ttsEngine", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "Wake Word") {            Row(verticalAlignment = Alignment.CenterVertically) {                Text("Hey NOUS", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface, modifier = Modifier.weight(1f))                Switch(checked = wakeWordActive, onCheckedChange = { /* Wake word toggle handled by VoiceModule */ })            }        }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "Speaker Recognition") { Text("Enrolled speakers: $speakerCount", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }    }}@Composablefun SecurityScreen(viewModel: NousViewModel, onBack: () -> Unit, modifier: Modifier = Modifier) {    val uiState by viewModel.uiState.collectAsState()    SettingScaffold("Security", onBack, modifier) {        GlassPanel(title = "App Lock") {            Row(verticalAlignment = Alignment.CenterVertically) {                Column(Modifier.weight(1f)) {                    Text(if (uiState.isLocked) "Locked" else "Unlocked", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface)                    Text("Biometric: ${if (uiState.biometricAvailable) "Available" else "Not available"}", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant)                }                Switch(checked = uiState.isLocked.not(), onCheckedChange = { /* Lock state managed by AppLockManager */ })            }        }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "Credential Vault") { Text("Encrypted storage for passwords, API keys, and cards.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "Audit Log") { Text("90-day encrypted audit trail of all security-sensitive operations.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "Backup & Restore") { Text("Encrypted full-app backup to user-selected location.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }    }}@Composablefun ConnectivityScreen(onBack: () -> Unit, modifier: Modifier = Modifier) {    SettingScaffold("Connectivity", onBack, modifier) {        GlassPanel(title = "Calls") { Text("Phone call integration via TelephonyManager.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "SMS") { Text("SMS send/receive via SmsManager.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "Contacts") { Text("Contact search via ContactsContract.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "Spam Detection") { Text("Local spam database + caller ID classification.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "SOS") { Text("Emergency SOS: power button x3, shake, or voice 'SOS'.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }    }}@Composablefun CognitiveScreen(onBack: () -> Unit, modifier: Modifier = Modifier) {    SettingScaffold("Cognitive Engine", onBack, modifier) {        GlassPanel(title = "Reasoning Depth") { Text("Balanced: 2 passes, self-correct on low confidence.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "Planning") { Text("Max sub-tasks per goal: 8. Replanning on failure: enabled.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "Decision Making") { Text("Risk threshold: 80%. Platt scaling calibration. Auto-clarify on low confidence.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "Reasoning Cache") { Text("In-memory cache of reasoning traces for common queries.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }    }}@Composablefun SelfModifyScreen(onBack: () -> Unit, modifier: Modifier = Modifier) {    SettingScaffold("Self-Modify (Hacker Mode)", onBack, modifier) {        GlassPanel(title = "Rhino JS Sandbox") {            Text("Sandboxed JavaScript runtime for custom automation scripts.\nPermissions: NO_FILE, NO_NETWORK, NO_REFLECTION.\nMemory limit: 64 MB. CPU timeout: 5 seconds.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface)        }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "Available APIs") {            Text("nous.say(text)\nnous.skill.{torch, volume, brightness, ...}.method()\nnous.memory.recall(query)\nnous.brain.process(input)", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant)        }    }}@Composablefun AboutScreen(appVersion: String, buildNumber: String, onBack: () -> Unit, modifier: Modifier = Modifier) {    SettingScaffold("About NOUS", onBack, modifier) {        GlassPanel(title = "Version") { Text("Version: $appVersion\nBuild: #$buildNumber\nFlavor: dev-debug", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "License") { Text("Proprietary — Copyright (c) 2026 Roshan. All rights reserved.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "Strategy Reference") { Text("NOUS — 35-module Android AI assistant.\n14 backend modules. 11 core modules. 4 native modules (JNI).", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant) }    }}@Composablefun DeveloperScreen(onBack: () -> Unit, modifier: Modifier = Modifier) {    SettingScaffold("Developer", onBack, modifier) {        GlassPanel(title = "Logs & Traces") { Text("Real-time logcat viewer with tag filtering.\nTimber tags: NOUS.*, NOUS.UI, NOUS.VM, NOUS.Boot.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "Telemetry") { Text("OpenTelemetry integration for distributed tracing.\nAudit log: JSONL format, 90-day retention, file-based.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }        Spacer(Modifier.size(16.dp))        GlassPanel(title = "Crash Markers") { Text("crash_markers.json tracks recent crashes.\n3+ crashes in 5 min triggers safe mode boot.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface) }    }}@Composableprivate fun SettingScaffold(title: String, onBack: () -> Unit, modifier: Modifier = Modifier, content: @Composable () -> Unit) {    Column(modifier = modifier.fillMaxSize().background(MaterialTheme.colorScheme.background)) {        Row(modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 12.dp), verticalAlignment = Alignment.CenterVertically) {            IconButton(onClick = onBack) { Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back", tint = MaterialTheme.colorScheme.onBackground) }            Text(title, style = MaterialTheme.typography.headlineLarge, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onBackground, modifier = Modifier.padding(start = 8.dp))        }        LazyColumn(modifier = Modifier.fillMaxSize(), contentPadding = PaddingValues(16.dp)) { item { content() } }    }}